// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(bool dummy) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        uint balBefore = address(c).balance;
        uint myBalBefore = address(this).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balAfter = address(c).balance;
        uint myBalAfter = address(this).balance;
        assertTrue(reverted == false && balAfter == balBefore && myBalAfter == myBalBefore);
    }

    function testFuzz_run(bool dummy) public {
        _run(dummy);
    }

    receive() external payable { }
}
